<?php require_once __DIR__.'/../includes/functions.php';require_role(['admin','finance','production']);$pdo=db();$stats=[];foreach([['orders','Total Order'],['users','Total User'],['payments','Pembayaran']] as $x){$stats[]=[$x[1],(int)$pdo->query("SELECT COUNT(*) FROM {$x[0]}")->fetchColumn()];}$revenue=(float)$pdo->query("SELECT COALESCE(SUM(total_amount),0) FROM orders")->fetchColumn();?><!doctype html><html lang="id"><head><?php include __DIR__.'/../includes/head.php';?></head><body><?php include __DIR__.'/../includes/header.php';?><main class="content"><p class="eyebrow">BACK OFFICE</p><h1>Dashboard</h1><div class="grid four"><?php foreach($stats as $x):?><div class="metric"><small><?=e($x[0])?></small><strong><?=number_format($x[1])?></strong></div><?php endforeach;?><div class="metric"><small>Omzet</small><strong>Rp <?=number_format($revenue,0,',','.')?></strong></div></div><nav class="admin-nav"><a href="orders.php">Orders</a><a href="payments.php">Payments</a><a href="production.php">Production</a><a href="customers.php">Customers</a></nav></main></body></html>